    21→    public static Entry init(List<RuleEntry> queue) {
    22→        Entry e = new Entry();
    23→        if (queue.size() > 0) {
    24→            e.start = queue.get(0).start;
    25→            RuleEntry lastOne = queue.get(queue.size() - 1);
    26→            e.lastPosition = lastOne.start + lastOne.length;
    27→        }
    28→        return e;
    29→    }
