    51→    // e1, e2을 e0에 붙여서 새로운 텀을 만든다.
    52→    public static RuleEntry mergeNewEntry(RuleEntry e0, RuleEntry e1, RuleEntry e2, String type) {
    53→        RuleEntry e3 = mergeNewEntry(e0, e1, type);
    54→        e3.length = (e2.start + e2.length - e3.start);
    55→        e3.endOffset = e2.endOffset;
    56→        e3.type = type;
