   243→    protected static RuleEntry mergeQueueQuery(int qinx, int typeContinuous, List<RuleEntry> queue, List<RuleEntry> subQueue) {
   244→        int removeInx = qinx - typeContinuous;
   245→        if (removeInx < 0) {
   246→            removeInx = 0;
