   248→        }
   249→
   250→        if (queue.get(removeInx + typeContinuous - 1).type == SYMBOL) {
   251→            typeContinuous--;
   252→        }
   253→
   254→        if (typeContinuous == 1) {
   255→            logger.trace("queue has only one entry. so don't merge it");
   256→            return null;
   257→        }
   258→
   259→        logger.trace("queue[{}]={}", removeInx + typeContinuous - 1, queue.get(removeInx + typeContinuous - 1));
   260→
   261→        RuleEntry entry = queue.get(removeInx).clone();
   262→        logger.trace("ENTRY-CLONE:{}", entry);
   263→        // 클로닝 되기 때문에 동의어를 반드시 삭제 해 주어야 한다.
