   272→        for (; typeContinuous > 0; typeContinuous--) {
   273→            subEntry = queue.remove(removeInx);
   274→            logger.trace("pop entry:{}/{}:{}[{}~{}] / {}", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset, subEntry.synonym);
   275→            if (type != subEntry.type) {
   276→                type = null;
   277→            }
   278→            int start = subEntry.start;
   279→            int length = subEntry.length;
   280→            int endOffset = subEntry.endOffset;
   281→            if (subQueue != null) {
   282→                if (subEntry.type == UNIT_ALPHA) {
   283→                    // 단위명이었지만 규칙에 의해 모델명으로 전환되는 경우.
   284→                    // 단위명과 숫자를 구분해준다.
   285→                    logger.trace("subList:{}{}", "", subEntry.subEntry);
   286→                    if (subEntry != null && subEntry.subEntry.size() > 0) {
   287→                        RuleEntry number = subEntry.subEntry.remove(0);
   288→                        subQueue.add(number);
   289→                        subEntry.start += number.length;
   290→                        subEntry.length -= number.length;
   291→                        subEntry.startOffset += number.length;
   292→                        subEntry.type = ALPHA;
   293→                        // 단위명 뒤 엔트리가 영문이라면 단위명과 합치도록 한다. (118X71WXU3 -> 71W + XU -> 71 + WXU)
   294→                        if (removeInx < queue.size() &&
   295→                                (nextEntry = queue.get(removeInx)).type == ALPHA &&
   296→                                nextEntry.startOffset == subEntry.endOffset) {
   297→                            subEntry.length += nextEntry.length;
   298→                            subEntry.endOffset += nextEntry.length;
   299→                            queue.remove(removeInx);
   300→                            typeContinuous--;
   301→                        }
   302→                    } else {
   303→                        subEntry.type = ALPHANUM;
   304→                    }
   305→                    subEntry.synonym = null;
   306→                    subQueue.add(subEntry);
   307→                } else {
   308→                    subQueue.add(subEntry);
   309→                }
   310→            }
   311→            logger.trace("merge : {}[{}:{}/{}~{}]", subEntry, subEntry.start, subEntry.length, subEntry.startOffset, subEntry.endOffset);
   312→            logger.trace("subQueue : {}", subQueue);
   313→            entry.length = start + length - entry.start;
   314→            entry.endOffset = endOffset;
   315→        }
   316→        entry.type = type;
   317→        queue.add(removeInx, entry);
   318→        return entry;
   319→    }
