   327→    public static RuleEntry modifyRuleEntry(boolean fullExtract, AnalyzerOption option, RuleEntry e0, RuleEntry e1,
   328→                                            CharVector unitCandidate, CharSequence[] units,
   329→                                            String unitType) {
   330→        RuleEntry backup = e0.clone();
   331→        if (fullExtract) {
   332→            e0.subEntry = new ArrayList<>();
   333→            e0.subEntry.add(backup);
   334→        }
   335→
   336→        CharSequence[] synonyms = null;
   337→        // 색인시 단위명 동의어는 추출하지 않는다
   338→        if (fullExtract && units != null && option.useForQuery()) {
   339→            if (units != null && !(units.length == 1 && unitCandidate.equals(units[0]))) {
   340→                synonyms = new CharVector[units.length];
   341→                for (int inx = 0; inx < units.length; inx++) {
   342→                    char[] ubuf = new char[e0.length + units[inx].length()];
   343→                    CharVector unitInx = CharVector.valueOf(units[inx]);
   344→                    System.arraycopy(e0.buf, e0.start, ubuf, 0, e0.length);
   345→                    System.arraycopy(unitInx.array(), unitInx.offset(), ubuf,
   346→                            e0.length, units[inx].length());
   347→                    synonyms[inx] = new CharVector(ubuf);
   348→                }
   349→            }
   350→        }
   351→
   352→        // 변형숫자가 있다면, 일반숫자로 바꾸어 다시한 번 단위명을 산출한다.
   353→        if (e0.type == NUMBER_TRANS) {
   354→            CharVector number = e0.makeTerm(null);
   355→            number = new CharVector(number.toString().replaceAll(",", ""));
   356→            // 변형숫자를 일반숫자로 변경했는데 변경사항이 없다면 동의어를 만들지 않음.
   357→            if (backup.length != number.length()) {
   358→                String unitStr = number + unitCandidate.toString();
   359→                e1 = new RuleEntry(unitStr.toCharArray(), 0, unitStr.length(),
   360→                        e0.startOffset, e0.endOffset + unitCandidate.length(), UNIT);
   361→                e0.subEntry.add(0, e1);
   362→                logger.trace("E0:{}/E1:{}", e0, e1);
   363→            }
   364→        }
   365→
   366→        if (fullExtract) {
   367→            if (e0.subEntry == null) {
   368→                e0.subEntry = new ArrayList<>();
   369→            }
   370→            if (synonyms != null && synonyms.length > 0) {
   371→                e0.synonym = synonyms;
   372→            }
   373→        }
   374→
   375→        e0.length += unitCandidate.length();
   376→        e0.endOffset += unitCandidate.length();
   377→
   378→        if (unitType == ALPHA) {
   379→            e0.type = UNIT_ALPHA;
   380→        } else {
   381→            e0.type = UNIT;
   382→        }
   383→
   384→        return e1;
   385→    }
