   761→
   762→                val nextNextEntry: RuleEntry?
   763→
   764→                if (currentEntry.length == 1 && ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start].code))) || currentEntry.type == NUMBER)) {
   765→                    if (iter.hasNext() && nextEntry == null) {
   766→                        nextEntry = iter.next()
   767→                        if (isConnected(currentEntry, nextEntry)) {
   768→                            combineNextEntry(tmpList, currentEntry, nextEntry, ALPHANUM)
   769→                        }
   770→                    }
   771→
   772→                    if (nextEntry != null && nextEntry.length == 1 && ((nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code))) || nextEntry.type == NUMBER)) {
   773→                        if ((currentEntry.type == NUMBER && (nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code))) || ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start].code))) && nextEntry.type == NUMBER))) {
   774→                            if (iter.hasNext()) {
   775→                                nextNextEntry = iter.next()
   776→                                if (isConnected(currentEntry, nextEntry) && isConnected(nextEntry, nextNextEntry)) {
   777→                                    if (nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start].code)) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start].code)))) {
   778→                                        combineNextNextEntry(tmpList, currentEntry, nextEntry, nextNextEntry, ALPHANUM)
   779→                                    }
   780→                                } else if (isConnected(nextEntry, nextNextEntry)) {
