   782→                                        combineNextNextEntry(tmpList, nextEntry, nextNextEntry, ALPHANUM)
   783→                                    }
   784→                                }
   785→                                currentEntry = nextEntry
   786→                                nextEntry = nextNextEntry
   787→                            }
